return items.map(item => {
  const min = 60;
  const max = 180;
  const delay = Math.floor(Math.random() * (max - min + 1)) + min;

  return {
    json: {
      ...item.json,
      delay
    }
  };
});

const final = {};
let mensagens = [];

for (const item of items) {
  const json = item.json;

  // Junta mensagens
  if (json.Messagem) {
    mensagens.push(json.Messagem);
  }

  // Copia os demais campos (sem sobrescrever mensagens)
  for (const key in json) {
    if (key !== 'Messagem') {
      final[key] = json[key];
    }
  }

  // Extrai o telefone e insere sempre o 9 após o DDD
  if (json.From && !final.telefone) {
    const raw = json.From.split('@')[0]; // Ex: 557193643490
    const ddi = raw.slice(0, 2);          // 55
    const ddd = raw.slice(2, 4);          // 71
    const restante = raw.slice(4);        // 93643490 (ou sem 9, tanto faz)

    // Sempre adiciona o 9 no início do restante
    const numeroCom9 = '9' + restante;

    final.telefone = `${ddi}${ddd}${numeroCom9}`; // Ex: 5571993643490
  }
}

final.Messagem = mensagens.join(', '); // ou '\n' se preferir

return [
  {
    json: final
  }
];

const texto = $items("Orquestrador")[0].json.output;
const mensagens = texto
  .split(/\n+/)  // split por uma ou mais quebras de linha reais
  .map(p => p.trim())
  .filter(p => p.length > 0);

return mensagens.map(mensagem => ({
  json: { text: mensagem }
}));

